          className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors ${filtro.modo === o.id ? 'bg-white text-[#18181B] shadow-sm' : 'text-[#71717A] hover:text-[#27272A]'}`}>
          {o.label}
