17	  @Get('acesso')
18	  async getAcesso() {
19	    const nets = os.networkInterfaces();
20	    const todos: string[] = [];
21	    for (const iface of Object.values(nets)) {
22	      for (const net of iface ?? []) {
23	        if (net.family === 'IPv4' && !net.internal) todos.push(net.address);
24	      }
25	    }
26	    // Prioriza 192.168.x.x (WiFi doméstico/corporativo) e 10.x.x.x (redes corporativas).
27	    // Descarta 172.16-31.x.x que são WSL, Docker, Hyper-V — não acessíveis por dispositivos reais.
28	    const score = (ip: string) => {
29	      if (/^192\.168\./.test(ip)) return 0;
30	      if (/^10\./.test(ip)) return 1;
31	      if (/^172\.(1[6-9]|2\d|3[01])\./.test(ip)) return 99; // virtual — vai por último
32	      return 2;
33	    };
34	    const ips = todos.sort((a, b) => score(a) - score(b));
35	
36	    const { data } = await this.supabase.client
37	      .from('platform_settings')
38	      .select('config')
39	      .eq('id', 1)
40	      .maybeSingle();
41	    const cfg = ((data?.config ?? {}) as Record<string, any>);
42	    return {
43	      lan_ips: ips,
44	      porta: 4028,
45	      cloudflare_domain: cfg.cloudflare_domain || null,
46	    };
47	  }
