49	  @Get()
50	  async listarRestaurantes(
51	    @Query()
52	    query: {
53	      state?: string;
54	      city?: string;
55	      neighborhood?: string;
56	      cep?: string;
57	      lat?: string;
58	      lng?: string;
59	      raio_km?: string;
60	    },
61	    @Headers('authorization') authorization?: string,
62	  ) {
63	    let q = this.supabase.client
64	      .from('restaurants')
65	      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, aparencia, frete_motoboy, lat, lng')
66	      .not('slug', 'is', null)
67	      .eq('bloqueado', false);
68	
69	    if (query.state) q = q.ilike('state', query.state);
70	    if (query.city) q = q.ilike('city', query.city);
71	    if (query.neighborhood) q = q.ilike('neighborhood', query.neighborhood);
72	    if (query.cep) q = q.ilike('cep', `${query.cep.replace(/\D/g, '').slice(0, 5)}%`);
