// Script temporario, uso unico - importar public/estoque.json pro restaurante id=1.
require('dotenv').config();
const { createClient } = require('@supabase/supabase-js');

const RESTAURANT_ID = 1;
const LIMITE_ESTOQUE_VALIDO = 100000;

async function main() {
  const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
  const estoque = require('../public/estoque.json');

  const categoriasPrincipais = [...new Set(estoque.produtos.map((p) => p.grupo.split(':')[0].trim()))];

  const { data: existentes, error: errCat } = await supabase
    .from('categories')
    .select('id, name, restaurant_id')
    .or(`restaurant_id.eq.${RESTAURANT_ID},restaurant_id.is.null`);
  if (errCat) throw errCat;

  const mapaCategoria = new Map();
  for (const c of existentes) mapaCategoria.set(c.name.toLowerCase(), c.id);

  for (const nome of categoriasPrincipais) {
    if (mapaCategoria.has(nome.toLowerCase())) continue;
    const { data, error } = await supabase
      .from('categories')
      .insert({ name: nome, restaurant_id: RESTAURANT_ID })
      .select('id, name')
      .single();
    if (error) throw error;
    mapaCategoria.set(data.name.toLowerCase(), data.id);
    console.log('categoria criada:', data.name, '->', data.id);
  }

  let criados = 0;
  let zerados = 0;
  for (const p of estoque.produtos) {
    const categoriaNome = p.grupo.split(':')[0].trim();
    const category_id = mapaCategoria.get(categoriaNome.toLowerCase());
    const estoqueValido = p.qtd_atual <= LIMITE_ESTOQUE_VALIDO;
    if (!estoqueValido) zerados++;

    const { error } = await supabase.from('products').insert({
      name: p.descricao,
      description: null,
      price: 0,
      preco_custo: 0,
      category_id,
      restaurant_id: RESTAURANT_ID,
      quantidade_estoque: estoqueValido ? p.qtd_atual : 0,
      quantidade_minima: 0,
      is_active: true,
    });
    if (error) {
      console.error('ERRO no produto', p.codigo, p.descricao, '->', error.message);
      continue;
    }
    criados++;
  }

  console.log(`\nProdutos criados: ${criados}/${estoque.produtos.length}`);
  console.log(`Estoque zerado por valor corrompido: ${zerados}`);
}

main().catch((e) => { console.error(e); process.exit(1); });

