// Script temporario, uso unico - atualiza/cria produtos do restaurante id=1
// a partir de public/estoque.json (v2, com preco/custo/categoria/impressora/tags/imagem).
require('dotenv').config();
const { createClient } = require('@supabase/supabase-js');

const RESTAURANT_ID = 1;
const norm = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');

// Correções manuais confirmadas (nome no arquivo -> nome já cadastrado no banco)
const CORRECOES_NOME = {
  'ref4pcamaraorosaalhoeoleo': 'ref4pcamaraorosaalhoeolho',
};

const TAG_MAP = { 'Lançamentos': 'lancamentos', 'Em Promoção': 'promo' };

async function main() {
  const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
  const itens = require('../public/estoque.json');

  const { data: existentes, error: e1 } = await supabase.from('products').select('id,name').eq('restaurant_id', RESTAURANT_ID);
  if (e1) throw e1;
  const { data: categorias, error: e2 } = await supabase.from('categories').select('id,name').eq('restaurant_id', RESTAURANT_ID);
  if (e2) throw e2;
  const mapaCategoria = new Map(categorias.map((c) => [c.name.toLowerCase(), c.id]));

  let atualizados = 0, criados = 0;

  for (const p of itens) {
    let alvo = norm(p.nome);
    alvo = CORRECOES_NOME[alvo] || alvo;
    const existente = existentes.find((e) => norm(e.name) === alvo);

    const categoriaNome = p.categoria.split(':')[0].trim();
    const category_id = mapaCategoria.get(categoriaNome.toLowerCase());
